import re
from collections import Counter
dna = ''.join(open('region.fasta').read().strip().split('\n')[1:])
n=len(dna)

# find exact repeated k-mers (k=25..40) with multiple occurrences
for k in [20,25,30,31,35,40,50]:
    cnt = Counter(dna[i:i+k] for i in range(n-k+1))
    reps = {s:c for s,c in cnt.items() if c>2}
    if reps:
        print("k=",k,"num repeated:",len(reps))
        for s,c in sorted(reps.items(), key=lambda x:-x[1])[:5]:
            print("  ",c,s)
